import { Key, useCallback, useMemo, useState } from 'react';

import useControlled from '@proton/hooks/useControlled';

import { generateUID } from '../../helpers';

export interface ModalStateProps {
    open: boolean;
    onClose: () => void;
    onExit: () => void;
}

type ModalStateOptions = Partial<Pick<ModalStateProps, 'open' | 'onClose' | 'onExit'>>;
type ModalStateReturnTuple = [
    modalProps: ModalStateProps,
    openModal: (newValue: boolean) => void,
    renderModal: boolean,
];
export interface ModalStateReturnObj {
    modalProps: ModalStateReturnTuple[0];
    openModal: ModalStateReturnTuple[1];
    render: ModalStateReturnTuple[2];
}

const useModalState = (options?: ModalStateOptions): ModalStateReturnTuple => {
    const { open: controlledOpen, onClose, onExit } = options || {};

    const [key, setKey] = useState(() => generateUID());
    const [open, setOpen] = useControlled(controlledOpen);
    const [render, setRender] = useState(!!open);

    const handleSetOpen = useCallback((newValue: boolean) => {
        if (newValue) {
            setOpen(true);
            setRender(true);
        } else {
            setOpen(false);
        }
    }, []);

    const handleClose = useCallback(() => {
        handleSetOpen(false);
        onClose?.();
    }, [handleSetOpen, onClose]);

    const handleExit = useCallback(() => {
        setRender(false);
        setKey(generateUID());
        onExit?.();
    }, [onExit]);

    const modalProps: ModalStateProps & { key: Key } = useMemo(
        () => ({
            key,
            open: !!open,
            onClose: handleClose,
            onExit: handleExit,
        }),
        [key, open, handleClose, handleExit]
    );

    return [modalProps, handleSetOpen, render] as const;
};

export const useModalStateObject = (options?: ModalStateOptions): ModalStateReturnObj => {
    const [modalProps, openModal, render] = useModalState(options);

    return {
        modalProps,
        openModal,
        render,
    };
};

export default useModalState;
import type { AsyncCallback } from '@proton/pass/types';
import { getEpoch } from '@proton/pass/utils/time/epoch';
import lastItem from '@proton/utils/lastItem';

type MaxAgeMemoizeOptions = { maxAge: number };

export type MaxAgeMemoizedFn<F extends AsyncCallback> = (
    ...args: [...Parameters<F>, options: MaxAgeMemoizeOptions]
) => ReturnType<F>;

/** Memoizes the result of an asynchronous function with a specified maximum age.
 * Returns a wrapped function that accepts a trailing `maxAge` parameter in seconds */
export const maxAgeMemoize = <F extends AsyncCallback>(fn: F) => {
    const cache: Map<string, { calledAt: number; result: ReturnType<F> }> = new Map();

    return (async (...args: [...Parameters<F>, options: MaxAgeMemoizeOptions]) => {
        const calledAt = getEpoch();
        const { maxAge } = lastItem(args) as MaxAgeMemoizeOptions;

        const memoArgs = JSON.stringify(args.slice(0, -1));
        const cached = cache.get(memoArgs);

        if (cached && calledAt - cached.calledAt < maxAge) return cached.result;
        else {
            const result = await fn(...args);
            cache.set(memoArgs, { calledAt, result });
            return result;
        }
    }) as MaxAgeMemoizedFn<F>;
};
# Pass Bridge

### Usage

#### Factory

Import the factory function and create a `PassBridge` instance with the necessary options.

```ts
import { createPassBridge } from '@proton/pass/lib/bridge';

const PassBridge = createPassBridge({ api, user, addresses, authStore });
```

#### React

In react, you can use the `PassBridgeProvider` component which will take care of creating the bridge and use the `usePassBridge` hook in the subtree.

```tsx
import { PassBridgeProvider, usePassBridge } from '@proton/pass/lib/bridge/PassBridgeProvider';
```

⚠️ Make sure the underlying models are available when creating the context. `PassBridge` requires the user and addresses to be fully loaded to instantiate properly.

### Aliases

#### Integration example

```ts
// Get all the aliases for the default user vault. If no vaults
// are available, a default one will be created.
const defaultVault = await PassBridge.vault.getDefault();
const aliasItems = await PassBridge.alias.getAllByShareId(defaultVault.shareId);

// Relevant information for alias items :
const { item, aliasDetails } = aliasItems[0]
const aliasEmail = aliasDetails.aliasEmail
const aliasMailboxes = aliasDetails.mailboxes
const { name, note } = item.data.metadata
// note is obfuscated, if you need to read it :
import { deobfuscate } from '@proton/pass/utils/obfuscate/xor'
const clearNote = deobfuscate(note)

// Before creating a new alias, you need to request the current
// alias options - these options have a validity window of 10 minutes
// after which you will have to re-query the alias options. These options
// will give you the available suffixes and mailboxes
const aliasOptions = await PassBridge.alias.getAliasOptions(defaultVault.shareId);

// Creating an alias : let the user select the desired prefix, suffix and target mailbox.
// You can validate the final aliasEmail before submitting (prefix + suffix).
const prefix = 'some-user-input';
const mailbox = aliasOptions.mailboxes[0];
const { suffix, signedSuffix } = aliasOptions.suffixes[1];
const aliasEmail = `${prefix}${signedSuffix}`;

const alias = await PassBridge.alias.create({
    shareId: defaultVault.shareId,
    name: 'Alias for ProtonMail',
    note: 'Alias created from mail widget',
    alias: {
        mailbox,
        signedSuffix,
        prefix,
        aliasEmail,
    },
});
